import {solutionMass,moleAccount,reactionAccount,concentrationTasks,moleTasks,ratioTasks} from './amount-models.js?v=20261023-physicscomplete01';
import {showSolution,showMole,showRatio} from './amount-scenes.js?v=20261023-physicscomplete01';
const fmt=n=>Number(n.toPrecision(10));
const $=s=>document.querySelector(s),btn=(id,t)=>`<button class="secondary" id="${id}">${t}</button>`,input=(id,label,value='')=>`<label class="field-label" for="${id}">${label}</label><input class="lab-input" id="${id}" type="number" step="any" value="${value}">`;
export function mountAmountWidget(l,p,root,{save,done,feedback}){const w=p.widget;w.task??=0;w.passed??=[];w.answers??={};const i=w.task;const again=()=>{save();mountAmountWidget(l,p,root,{save,done,feedback});};const success=message=>{if(!w.passed.includes(i))w.passed.push(i);save();$('#amountProgress').textContent=w.passed.length+' / 3 tasks correct';feedback(message);if(w.passed.length===3){p.widgetDone=true;save();done();feedback('All three calculation tasks complete. '+message);}};
 if(l.widget==='amount-concentration'){
 const t=concentrationTasks[i];w.answers[i]??={volume:'',mass:''};const a=w.answers[i];root.innerHTML=`<p><b>Solution task ${i+1} / 3</b></p><p>Concentration ${t.c} g/dm³. Total solution volume ${t.v} cm³. Convert the volume and calculate the solute mass.</p>`+input('solutionVolume','Volume / dm³',a.volume)+input('solutionMass','Solute mass / g',a.mass)+btn('checkSolution','Check the solution account')+btn('nextAmount','Next solution →')+`<p id="amountProgress">${w.passed.length} / 3 tasks correct</p><p class="micro-note">This is a calculation planner; the fill level is schematic, not a calibrated vessel.</p>`;showSolution(t.c,t.v);$('#solutionVolume').oninput=e=>{a.volume=e.target.value;save();};$('#solutionMass').oninput=e=>{a.mass=e.target.value;save();};$('#checkSolution').onclick=()=>{if(a.volume!==''&&a.mass!==''&&Math.abs(Number(a.volume)-t.v/1000)<=.0001&&Math.abs(Number(a.mass)-solutionMass(t.c,t.v))<=.001)success(`${t.v} cm³=${t.v/1000} dm³; mass=${solutionMass(t.c,t.v)} g.`);else feedback('Divide cm³ by 1000, then multiply concentration by volume in dm³. Use the total solution volume.',true);};$('#nextAmount').onclick=()=>{w.task=(i+1)%3;again();};return;
 }
 if(l.widget==='amount-moles'){
 const t=moleTasks[i];w.answers[i]??={mass:'',particles:''};const a=w.answers[i],result=moleAccount(t.n,t.mr);root.innerHTML=`<p><b>Mole task ${i+1} / 3: ${t.name}</b></p><p>Amount ${t.n} mol; relative ${t.symbol==='C'?'atomic':'formula'} mass ${t.mr}. Use 6.02×10²³ particles per mol. Calculate mass and number of the stated particles.</p>`+input('moleMass','Mass / g',a.mass)+input('moleParticles','Number of specified particles (e notation allowed)',a.particles)+btn('checkMoleAccount','Check amount, mass and count')+btn('nextAmount','Next substance →')+`<p id="amountProgress">${w.passed.length} / 3 tasks correct</p><div class="callout">The 3D view shows ONE representative particle. It does not display the enormous number in a mole. Atom counts within molecules are a separate question.</div>`;showMole(t.symbol);$('#moleMass').oninput=e=>{a.mass=e.target.value;save();};$('#moleParticles').oninput=e=>{a.particles=e.target.value;save();};$('#checkMoleAccount').onclick=()=>{if(a.mass!==''&&a.particles!==''&&Math.abs(Number(a.mass)-result.mass)<=.001&&Math.abs(Number(a.particles)-result.particles)<=1e18)success(`Mass=${fmt(result.mass)} g; specified particles=${result.particles.toExponential(3)}.`);else feedback('Mass=n×Mᵣ (or Aᵣ for an element). Particle number=n×6.02e23. Keep mass and particle count in their own boxes.',true);};$('#nextAmount').onclick=()=>{w.task=(i+1)%3;again();};return;
 }
 const t=ratioTasks[i];w.answers[i]??={input:'',output:'',mass:''};const a=w.answers[i],result=reactionAccount(t.mass,t.mr,t.from,t.to,t.targetMr);root.innerHTML=`<p><b>Reaction account ${i+1} / 3</b></p><p>${t.equation}</p><p>Given ${t.mass} g ${t.given} (Mᵣ/Aᵣ=${t.mr}); calculate ${t.target} (Mᵣ=${t.targetMr}). ${t.excess} is in excess. The given reactant reacts completely.</p>`+input('ratioInput',t.given+' amount / mol',a.input)+input('ratioOutput',t.target+' amount / mol',a.output)+input('ratioMass',t.target+' mass / g',a.mass)+btn('checkReactionAccount','Check the three-step calculation')+btn('nextAmount','Next equation →')+`<p id="amountProgress">${w.passed.length} / 3 tasks correct</p><p class="micro-note">Coefficients give mole ratios, not mass ratios. Calculated product is not an experimental yield.</p>`;showRatio(t);for(const[k,id]of[['input','ratioInput'],['output','ratioOutput'],['mass','ratioMass']])$('#'+id).oninput=e=>{a[k]=e.target.value;save();};$('#checkReactionAccount').onclick=()=>{if(['input','output','mass'].every(k=>a[k]!==''&&Math.abs(Number(a[k])-result[k])<=.001))success(`${fmt(result.input)} mol ${t.given} → ${fmt(result.output)} mol ${t.target} → ${fmt(result.mass)} g.`);else feedback(`First divide ${t.mass} by ${t.mr}. Then multiply by the coefficient ratio ${t.to}/${t.from}; finally multiply by ${t.targetMr}.`,true);};$('#nextAmount').onclick=()=>{w.task=(i+1)%3;again();};
}
